(6262852, 926003, 120171, '<td valign="top">I really like this image and hope its on the front page.</td>', 'I really like this image and hope its on the front page.', '2010-12-28 17:43:33.000000', NULL, 1),
(6262950, 926068, 114225, '<td valign="top">Great shot. The black and white was the perfect choice, as it adds a timelessness to this photo.</td>', 'Great shot. The black and white was the perfect choice, as it adds a timelessness to this photo.', '2010-12-28 19:40:40.000000', NULL, 1),
